/*
 * Function for MATLAB Function: '<S21>/rates_control_to_torque'
 * function [integralTerm, nextState] = integrate(obj, ...
 *                 integratorInput, lowerLimit, upperLimit, holdState)
 */
static void LW_ct_RflyDiscretePID_integrate(const
  RflyDiscretePID_LW_ctrl_V1_11_T *obj, real32_T integratorInput, real32_T
  lowerLimit, real32_T upperLimit, boolean_T holdState, real32_T *integralTerm,
  real32_T *nextState)
{
  /* 'RflyDiscretePID:188' currentState = constrain(obj.IntegratorState, lowerLimit, upperLimit); */
  /* CONSTRAIN 此处显示有关此函数的摘要 */
  /*    此处显示详细说明 */
  /*  min  = single(min); */
  /*  max = single(max); */
  /* 'constrain:6' if x > max */
  if (obj->IntegratorState > upperLimit) {
    /* 'constrain:7' y = max; */
    *integralTerm = upperLimit;
  } else if (obj->IntegratorState < lowerLimit) {
    /* 'constrain:8' elseif x < min */
    /* 'constrain:9' y = min; */
    *integralTerm = lowerLimit;
  } else {
    /* 'constrain:10' else */
    /* 'constrain:11' y = x; */
    *integralTerm = obj->IntegratorState;
  }

  /* 'RflyDiscretePID:189' if holdState */
  if (holdState) {
    /* 'RflyDiscretePID:190' integralTerm = currentState; */
    /* 'RflyDiscretePID:191' nextState = currentState; */
    *nextState = *integralTerm;
  } else {
    /* 'RflyDiscretePID:195' if obj.IntegratorMethod == 0 */
    if (obj->IntegratorMethod == 0) {
      /* 'RflyDiscretePID:196' integralTerm = currentState; */
      /* 'RflyDiscretePID:197' nextState = currentState + obj.SampleTime*integratorInput; */
      *nextState = obj->SampleTime * integratorInput + *integralTerm;
    } else if (obj->IntegratorMethod == 1) {
      /* 'RflyDiscretePID:198' elseif obj.IntegratorMethod == 1 */
      /* 'RflyDiscretePID:199' nextState = currentState + obj.SampleTime*integratorInput; */
      *nextState = obj->SampleTime * integratorInput + *integralTerm;

      /* 'RflyDiscretePID:200' integralTerm = nextState; */
      *integralTerm = *nextState;
    } else {
      /* 'RflyDiscretePID:201' else */
      /* 'RflyDiscretePID:202' nextState = currentState + obj.SampleTime/single(2)*( ... */
      /* 'RflyDiscretePID:203'                     integratorInput + obj.PreviousIntegratorInput); */
      *nextState = obj->SampleTime / 2.0F * (integratorInput +
        obj->PreviousIntegratorInput) + *integralTerm;

      /* 'RflyDiscretePID:204' integralTerm = nextState; */
      *integralTerm = *nextState;
    }

    /* 'RflyDiscretePID:207' nextState = constrain(nextState, lowerLimit, upperLimit); */
    /* CONSTRAIN 此处显示有关此函数的摘要 */
    /*    此处显示详细说明 */
    /*  min  = single(min); */
    /*  max = single(max); */
    /* 'constrain:6' if x > max */
    if (*nextState > upperLimit) {
      /* 'constrain:7' y = max; */
      *nextState = upperLimit;
    } else if (*nextState < lowerLimit) {
      /* 'constrain:8' elseif x < min */
      /* 'constrain:9' y = min; */
      *nextState = lowerLimit;
    } else {
      /* 'constrain:10' else */
      /* 'constrain:11' y = x; */
    }

    /* 'RflyDiscretePID:208' if obj.IntegratorMethod ~= 0 */
    if (obj->IntegratorMethod != 0) {
      /* 'RflyDiscretePID:209' integralTerm = nextState; */
      *integralTerm = *nextState;
    }
  }
}

