  /* 'RflyDiscretePID:67' proportionalGain = single(proportionalGain); */
  /* 'RflyDiscretePID:68' integralGain = single(integralGain); */
  /* 'RflyDiscretePID:69' derivativeGain = single(derivativeGain); */
