  /* 'RflyDiscretePID:72' if trackingEnabled */
  /* 'RflyDiscretePID:76' else */
  /* 'RflyDiscretePID:77' trackingSignal = single(0); */
  /* 'RflyDiscretePID:78' trackingGain = single(0); */
  /* 'RflyDiscretePID:81' resetActive = ~isempty(resetSignal) && resetSignal ~= 0; */
  /* 'RflyDiscretePID:82' [outputLower, outputUpper, outputLimited] = obj.readLimits(outputLimits); */
