        /* 'RflyDiscretePID:179' obj.FilterState = obj.FilterState + ... */
        /* 'RflyDiscretePID:180'                     halfSampleTime*(derivativeTerm + obj.PreviousDerivativeOutput); */
        obj->FilterState += (derivativeInput + obj->PreviousDerivativeOutput) *
          halfSampleTime;
