  /* 'RflyDiscretePID:92' backCalculationEnabled = obj.AntiWindupMethod == 2 && outputLimited; */
  backCalculationEnabled = (obj->AntiWindupMethod == 2);

  /* 'RflyDiscretePID:93' integratorEnabled = integralGain ~= 0 || trackingEnabled || backCalculationEnabled; */
  /* 'RflyDiscretePID:94' integratorInput = single(0); */
  halfSampleTime = 0.0F;

