static void LW_ctrl_V1_11_260_linearForm__m(boolean_T obj_hasLinear, int32_T
  obj_nvar, real_T workspace[5], const real_T H[16], const real_T f[4], const
  real_T x[5])
{
  int32_T b;
  int32_T beta1;
  int32_T d;
  int32_T e;
  int32_T ix;
  int32_T tmp;
  beta1 = 0;
  if (obj_hasLinear) {
    if ((uint8_T)obj_nvar - 1 >= 0) {
      memcpy(&workspace[0], &f[0], (uint8_T)obj_nvar * sizeof(real_T));
    }

    beta1 = 1;
  }

  if (obj_nvar != 0) {
    if (beta1 != 1) {
      memset(&workspace[0], 0, (uint8_T)obj_nvar * sizeof(real_T));
    }

    ix = 0;
    d = (obj_nvar - 1) * obj_nvar + 1;
    for (beta1 = 1; obj_nvar < 0 ? beta1 >= d : beta1 <= d; beta1 += obj_nvar) {
      e = (beta1 + obj_nvar) - 1;
      for (b = beta1; b <= e; b++) {
        tmp = b - beta1;
        workspace[tmp] += H[b - 1] * x[ix];
      }

      ix++;
    }
  }
}

