/*
 * Function for MATLAB Function: '<S30>/MATLAB Function3'
 * function obj = LowPassFilter1p(sample_freq, cutoff_freq)
 *  构造函数
 */
static LowPassFilter1p_LW_ctrl_V1_11_T *LowPassFilter1p_LowPassFilter_j
  (LowPassFilter1p_LW_ctrl_V1_11_T *obj, real_T sample_freq, real32_T
   cutoff_freq)
{
  LowPassFilter1p_LW_ctrl_V1_11_T *b_obj;
  real32_T dt;
  b_obj = obj;
  obj->State = 0.0F;
  obj->IsInitialized = false;

  /* 'LowPassFilter1p:1' handle */
  /* 'LowPassFilter1p:24' if nargin > 0 */
  /* 'LowPassFilter1p:25' obj.set_cutoff_frequency(sample_freq, cutoff_freq); */
  /*  计算滤波系数 Alpha */
  /*  alpha = dt / (RC + dt) */
  /* 'LowPassFilter1p:33' sf = single(sample_freq); */
  /* 'LowPassFilter1p:34' cf = single(cutoff_freq); */
  /*  简单保护：防止除以0 */
  /* 'LowPassFilter1p:37' if ~isfinite(sf) || ~isfinite(cf) || sf <= 0 || cf <= 0 */
  if (rtIsInfF((real32_T)sample_freq) || rtIsNaNF((real32_T)sample_freq) ||
      (rtIsInfF(cutoff_freq) || rtIsNaNF(cutoff_freq)) || (((real32_T)
        sample_freq <= 0.0F) || (cutoff_freq <= 0.0F))) {
    /* 'LowPassFilter1p:38' obj.Alpha = single(1.0); */
    /* 'LowPassFilter1p:10' single */
    /* 'LowPassFilter1p:10' Alpha */
    obj->Alpha = 1.0F;
  } else {
    /* 'LowPassFilter1p:42' dt = 1.0 / sf; */
    dt = 1.0F / (real32_T)sample_freq;

    /* 'LowPassFilter1p:43' rc = 1.0 / (6.2831853 * cf); */
    /*  2*pi*fc */
    /* 'LowPassFilter1p:45' alpha_val = dt / (rc + dt); */
    dt /= 1.0F / (6.28318548F * cutoff_freq) + dt;

    /*  限制范围 [0, 1] */
    /* 'LowPassFilter1p:48' if ~isfinite(alpha_val) */
    if (rtIsInfF(dt) || rtIsNaNF(dt)) {
      /* 'LowPassFilter1p:49' obj.Alpha = single(1.0); */
      /* 'LowPassFilter1p:10' single */
      /* 'LowPassFilter1p:10' Alpha */
      obj->Alpha = 1.0F;
    } else if (dt > 1.0F) {
      /* 'LowPassFilter1p:50' elseif alpha_val > 1.0 */
      /* 'LowPassFilter1p:51' obj.Alpha = single(1.0); */
      /* 'LowPassFilter1p:10' single */
      /* 'LowPassFilter1p:10' Alpha */
      obj->Alpha = 1.0F;
    } else {
      /* 'LowPassFilter1p:54' else */
      /* 'LowPassFilter1p:55' obj.Alpha = single(alpha_val); */
      /* 'LowPassFilter1p:10' single */
      /* 'LowPassFilter1p:10' Alpha */
      obj->Alpha = dt;
    }
  }

  return b_obj;
}

