  /* 'liftwingFlatnessSolver:35' obj.xw_prev = xc0; */
  /* 'liftwingFlatnessSolver:36' obj.yb_prev = yc0; */
  /* 'liftwingFlatnessSolver:37' obj.zw_prev = single([0; 0; 1]); */
  /* 'liftwingFlatnessSolver:38' obj.R_prev  = single([xc0, yc0, single([0; 0; 1])]); */
  obj->zw_prev[0] = 0.0F;
