    /*  f_{r,z_b} = -T_z, T_z >= 0, therefore f_{r,z_b} <= 0 */
    /*  ------------------------------------------------------ */
    /* 'liftwingFlatnessSolver:855' candThrustOK(i) = (fi <= single(0)); */
    candThrustOK[LW_ctrl_V1_11_260814_B.bestIdx] =
      (LW_ctrl_V1_11_260814_B.Aalpha <= 0.0F);

    /*  ------------------------------------------------------ */
    /*  Optional heading / yaw branch check */
    /*  ------------------------------------------------------ */
    /* 'liftwingFlatnessSolver:860' if enforce_yaw_check */
