  x[1] = ((!rtIsInfF(LW_ctrl_V1_11_260814_B.zb_c[1])) && (!rtIsNaNF
           (LW_ctrl_V1_11_260814_B.zb_c[1])));
  x[2] = ((!rtIsInfF(LW_ctrl_V1_11_260814_B.zb_c[2])) && (!rtIsNaNF
           (LW_ctrl_V1_11_260814_B.zb_c[2])));
  e_y = true;
