      /* '<S98>:1:99' gam1 = double(LW_MIXER_GAM); */
      /*  ========================================================== */
      /*  5. 权重矩阵构建与 Quadprog 求解 */
      /*  ========================================================== */
      /* '<S98>:1:104' Wu = diag(double([LW_W_FZ, LW_W_TAOX, LW_W_TAOY, LW_W_TAOZ])); */
      memset(&LW_ctrl_V1_11_260814_B.Wu[0], 0, sizeof(real_T) << 4U);
      LW_ctrl_V1_11_260814_B.Wu[0] = LW_W_FZ;
