      /* '<S98>:1:108' Tm = sum(delta_l(1:Nm)) / Nm; */
      LW_ctrl_V1_11_260814_B.T_hover = (((LW_ctrl_V1_11_260814_DW.delta_l[0] +
        LW_ctrl_V1_11_260814_DW.delta_l[1]) + LW_ctrl_V1_11_260814_DW.delta_l[2])
        + LW_ctrl_V1_11_260814_DW.delta_l[3]) / 4.0;

      /* '<S98>:1:109' delta_m = zeros(N_total, 1, 'double'); */
      /* '<S98>:1:110' delta_m(1:Nm) = Tm; */
      /* '<S98>:1:111' delta0 = delta_m; */
