      /* '<S98>:1:115' f = -(gam1 * u_v' * Wu * B + delta_m' * Wm)'; */
      /* '<S98>:1:116' options = optimoptions(@quadprog, 'Algorithm', 'active-set', 'OptimalityTolerance', 1e-8, 'MaxIterations', 20); */
      /* '<S98>:1:117' ws = optimwarmstart(delta0, options, "MaxLinearEqualities", 0, 'MaxLinearInequalities', 0); */
      LW_ctrl_V1_11_260814_DW.delta_l[0] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_B.ws.X[0] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_DW.delta_l[1] = LW_ctrl_V1_11_260814_B.T_hover;
