      LW_ctrl_V1_11_260814_DW.delta_l[2] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_B.ws.X[2] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_DW.delta_l[3] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_B.ws.X[3] = LW_ctrl_V1_11_260814_B.T_hover;
      LW_ctrl_V1_11_260814_B.ws.Options.InitDamping = 0.01;
      for (LW_ctrl_V1_11_260814_B.i = 0; LW_ctrl_V1_11_260814_B.i < 7;
           LW_ctrl_V1_11_260814_B.i++) {
        LW_ctrl_V1_11_260814_B.ws.Options.FiniteDifferenceType[LW_ctrl_V1_11_260814_B.i]
          = c_FiniteDifferenceType[LW_ctrl_V1_11_260814_B.i];
      }

      LW_ctrl_V1_11_260814_B.ws.Options.SpecifyObjectiveGradient = false;
      LW_ctrl_V1_11_260814_B.ws.Options.ScaleProblem = false;
      LW_ctrl_V1_11_260814_B.ws.Options.SpecifyConstraintGradient = false;
      LW_ctrl_V1_11_260814_B.ws.Options.NonFiniteSupport = true;
      LW_ctrl_V1_11_260814_B.ws.Options.IterDisplaySQP = false;
      LW_ctrl_V1_11_260814_B.ws.Options.FiniteDifferenceStepSize = -1.0;
      LW_ctrl_V1_11_260814_B.ws.Options.MaxFunctionEvaluations = -1.0;
      LW_ctrl_V1_11_260814_B.ws.Options.IterDisplayQP = false;
      LW_ctrl_V1_11_260814_B.ws.Options.PricingTolerance = 0.0;
      for (LW_ctrl_V1_11_260814_B.i = 0; LW_ctrl_V1_11_260814_B.i < 10;
           LW_ctrl_V1_11_260814_B.i++) {
        LW_ctrl_V1_11_260814_B.ws.Options.Algorithm[LW_ctrl_V1_11_260814_B.i] =
          c_Algorithm[LW_ctrl_V1_11_260814_B.i];
      }

