        /* 'LowPassFilter1p:97' obj.IsInitialized = true; */
        LW_ctrl_V1_11_260814_DW.lpf_stick_x.IsInitialized = true;

        /* '<S89>:1:218' lpf_stick_y.reset(stick_xyzr(2)); */
        /*  重置滤波器状态 */
        /* 'LowPassFilter1p:96' obj.State = single(sample); */
        /* 'LowPassFilter1p:14' single */
