        /* '<S41>:1:242'         single(v_wind(:)), ... */
        /* '<S41>:1:243'         traj_flag_flat); */
        LW_ctrl_V1_11_260814_B.c_b[0] = LW_ctrl_V1_11_260814_B.c_aero;
