        LW_ctrl_V1_11_260814_DW.yb_hist[0] = LW_ctrl_V1_11_260814_B.R_eb[3];
        LW_ctrl_V1_11_260814_DW.zb_hist[0] = LW_ctrl_V1_11_260814_B.R_eb[6];
