            /* '<S40>:1:302' state = true; */
            /* '<S40>:1:303' timer = current_timer; */
            LW_ctrl_V1_11_260814_B.Add = LW_ctrl_V1_11_260814_DW.timer_landed;

            /*  保持计时或封顶 */
