            /*  当前是 false，但在尝试变 true */
            /* '<S40>:1:306' timer = current_timer + dt; */
            LW_ctrl_V1_11_260814_B.Add = LW_ctrl_V1_11_260814_DW.timer_landed +
              LW_ctrl_V1_11_260814_B.sf_hrt_timestamp_k.dt;

            /* '<S40>:1:307' if timer >= time_threshold */
            if (LW_ctrl_V1_11_260814_B.Add >= LNDMC_TRIG_TIME / 3.0F * (real32_T)
                LW_ctrl_V1_11_260814_B.r_m) {
              /* '<S40>:1:308' state = true; */
              LW_ctrl_V1_11_260814_DW.state_landed = true;
            } else {
              /* '<S40>:1:309' else */
              /* '<S40>:1:310' state = false; */
            }
