        LW_ctrl_V1_11_260814_B.sf_yawrate_deadzone1.y;

      /* MATLAB Function: '<S114>/nan_inf4' */
      LW_ctrl_V1_11_260814_nan_inf0_m
        (LW_ctrl_V1_11_260814_B.uORBReadFunctionCallTrigger11_l.yaw,
         &LW_ctrl_V1_11_260814_B.sf_nan_inf4);

      /* MATLAB Function: '<S114>/yawrate_deadzone' */
