        /* '<S144>:1:14' y = single((u - RCMid + deadZone)*k); */
        LW_ctrl_V1_11_260814_B.norm_proj = (LW_ctrl_V1_11_260814_B.sf_nan_inf4.y
          + LW_MAN_WZ_DZ) * LW_ctrl_V1_11_260814_B.aSinInput;
