      /* MATLAB Function: '<S114>/nan_inf5' */
      LW_ctrl_V1_11_260814_nan_inf0_m(LW_ctrl_V1_11_260814_B.throttle,
        &LW_ctrl_V1_11_260814_B.sf_nan_inf5);

      /* MATLAB Function: '<S114>/f1' incorporates:
       *  Constant: '<S114>/Constant2'
       */
      /* Function description: */
      /*   throttle curve. When the throttle is in the middle position, the output */
      /*   is hovering throttle value. */
      /* Input: */
      /*   in: normalized throttle, range from 0 to 1 */
      /*   hover: hovering throttle value */
      /* Output: */
      /*   y: processed throttle value */
      /*  if in < 0.5 */
      /*  	y=2 * in * hover; */
      /*  else */
      /*  	y=hover + 2 * (in - 0.5) * (1.0 - hover); */
      /*  end */
      /* MATLAB Function 'navigator/navigator_manual/f1': '<S122>:1' */
      /* '<S122>:1:16' max_out = min(2.0 * hover, 1.0); */
      /* '<S122>:1:17' y = max_out * in; */
      LW_ctrl_V1_11_260814_B.qm = 2.0F * LW_THR_HOVER;
      if (!(LW_ctrl_V1_11_260814_B.qm <= 1.0F)) {
        LW_ctrl_V1_11_260814_B.qm = 1.0F;
      }

      /* Gain: '<S114>/Gain5' incorporates:
       *  MATLAB Function: '<S114>/f1'
       */
      LW_ctrl_V1_11_260814_B.qm = LW_ctrl_V1_11_260814_B.qm *
        LW_ctrl_V1_11_260814_B.sf_nan_inf5.y * 59.4490852F;

      /* Saturate: '<S114>/Saturation10' */
      if (LW_ctrl_V1_11_260814_B.qm > 19.62F) {
        LW_ctrl_V1_11_260814_B.qm = 19.62F;
      } else if (LW_ctrl_V1_11_260814_B.qm < 0.0F) {
        LW_ctrl_V1_11_260814_B.qm = 0.0F;
      }

      /* Gain: '<S114>/Gain4' incorporates:
       *  Saturate: '<S114>/Saturation10'
       */
      LW_ctrl_V1_11_260814_B.thrust = -44.5F * LW_MASS_K *
        LW_ctrl_V1_11_260814_B.qm;

      /* MATLAB Function: '<S114>/nan_inf2' */
      LW_ctrl_V1_11_260814_nan_inf0_m
        (LW_ctrl_V1_11_260814_B.uORBReadFunctionCallTrigger11_l.roll,
         &LW_ctrl_V1_11_260814_B.sf_nan_inf2);

      /* MATLAB Function: '<S114>/rollrate_deadzone' */
      /* Function description: */
