      /* MATLAB Function 'navigator/navigator_manual/pitchrate_deadzone': '<S136>:1' */
      /* '<S136>:1:4' RCMin = single(-1); */
      /* '<S136>:1:5' RCMax = single(1); */
      /* '<S136>:1:6' RCMid = ((RCMin + RCMax)/2); */
      /* '<S136>:1:7' deadZone = LW_MAN_WY_DZ; */
