            /* 'LowPassFilter1p:53' obj.Alpha = single(0.0); */
            /* 'LowPassFilter1p:10' single */
            /* 'LowPassFilter1p:10' Alpha */
            LW_ctrl_V1_11_260814_DW.lpf_wz_sp.Alpha = 0.0F;
